def _numpy_div(a, b, replace_inf_with=1):
    with np.errstate(divide='ignore', invalid='ignore'):
        result = np.divide(a, b)
    return np.where(np.isinf(result), replace_inf_with, result)


def _get_numpy_array_distance(num1, num2, max_=1, use_log_scale=False,
    log_scale_similarity_threshold=0.1):
    if use_log_scale:
        num1 = numpy_apply_log_keep_sign(num1)
        num2 = numpy_apply_log_keep_sign(num2)
    diff = np.abs(num1 - num2)
    if use_log_scale:
        return np.minimum(max_, diff)
    else:
        divisor = (np.abs(num1) + np.abs(num2)) / max_
        divisor[divisor == 0] = 1
        return np.minimum(max_, diff / divisor)
